CREATE TABLE `email_targets` (
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `enabled` TINYINT(1) NOT NULL DEFAULT 0,
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `locale` TEXT NOT NULL DEFAULT ('en-CA'),
  `name` TEXT NOT NULL,
  `recipient_ciphertext` TEXT NOT NULL,
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `version` BIGINT NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  CONSTRAINT `email_targets_locale_check` CHECK ((`locale` IN ('en-CA', 'fr-CA', 'zh-CN'))),
  CONSTRAINT `email_targets_name_check` CHECK (((CHAR_LENGTH(`name`) >= 1) AND (CHAR_LENGTH(`name`) <= 128)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `email_test_deliveries` (
  `accepted_at` DATETIME(6) NULL,
  `attempts` INT NOT NULL DEFAULT 0,
  `automatic_cancellation_code` TEXT NOT NULL DEFAULT (''),
  `console_origin` TEXT NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `episode_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  `error_code` TEXT NOT NULL DEFAULT (''),
  `event_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `event_sequence` BIGINT NULL,
  `from_address` TEXT NOT NULL,
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `kind` TEXT NOT NULL DEFAULT ('test'),
  `lease_expires_at` DATETIME(6) NULL,
  `lease_owner` TEXT NOT NULL DEFAULT (''),
  `lease_token` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  `locale` TEXT NOT NULL DEFAULT ('en-CA'),
  `next_attempt_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `possible_duplicate` TINYINT(1) NOT NULL DEFAULT 0,
  `quota_descriptor` JSON NULL,
  `quota_rule_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  `recipient_ciphertext` TEXT NOT NULL,
  `request_key` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `scenario` TEXT NOT NULL,
  `state` TEXT NOT NULL DEFAULT ('pending'),
  `target_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `target_version` BIGINT NOT NULL,
  `template_version` TEXT NOT NULL,
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `version` BIGINT NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_email_test_deliveries_event_id` (`event_id`),
  UNIQUE KEY `uq_email_test_deliveries_request_key` (`request_key`),
  KEY `ix_email_test_deliveries_quota_rule_id` (`quota_rule_id`),
  KEY `ix_email_test_deliveries_target_id` (`target_id`),
  KEY `ix_email_quota_order` (`quota_rule_id`, `event_sequence`),
  KEY `ix_email_test_deliveries_retention_idx` (`updated_at`),
  KEY `ix_email_test_delivery_due` (`next_attempt_at`),
  CONSTRAINT `email_quota_descriptor_shape` CHECK (((((((`kind` = 'test') AND (`quota_rule_id` IS NULL)) AND (`episode_id` IS NULL)) AND (`event_sequence` IS NULL)) AND (`quota_descriptor` IS NULL)) OR ((((((`kind` = 'repository_quota') AND (`quota_rule_id` IS NOT NULL)) AND (`episode_id` IS NOT NULL)) AND (`event_sequence` > 0)) AND (`quota_descriptor` IS NOT NULL)) AND (LENGTH(`quota_descriptor`) <= 8192)))),
  CONSTRAINT `email_quota_sequence_required` CHECK (((`kind` <> 'repository_quota') OR (`event_sequence` IS NOT NULL))),
  CONSTRAINT `email_test_deliveries_attempts_check` CHECK (((`attempts` >= 0) AND (`attempts` <= 8))),
  CONSTRAINT `email_test_deliveries_automatic_cancellation_code_check` CHECK ((`automatic_cancellation_code` IN ('', 'rule_changed', 'rule_disabled', 'rule_deleted'))),
  CONSTRAINT `email_test_deliveries_kind_check` CHECK ((`kind` IN ('test', 'repository_quota'))),
  CONSTRAINT `email_test_deliveries_locale_check` CHECK ((`locale` IN ('en-CA', 'fr-CA', 'zh-CN'))),
  CONSTRAINT `email_test_deliveries_scenario_check` CHECK ((`scenario` IN ('warning', 'critical', 'resolved'))),
  CONSTRAINT `email_test_deliveries_state_check` CHECK ((`state` IN ('pending', 'delivering', 'retrying', 'accepted', 'dead')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `email_test_requests` (
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`),
  KEY `ix_email_test_requests_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `hf_blobs` (
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `hf_repo_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `sha256` VARCHAR(64) NOT NULL,
  `size` BIGINT NOT NULL,
  PRIMARY KEY (`hf_repo_id`, `sha256`),
  KEY `ix_hf_blobs_sha256` (`sha256`),
  CONSTRAINT `hf_blobs_sha256_check` CHECK (REGEXP_LIKE(`sha256`, '^[0-9a-f]{64}\\z', 'cn')),
  CONSTRAINT `hf_blobs_size_check` CHECK ((`size` >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `hf_commits` (
  `author` TEXT NULL,
  `commit_sha` VARCHAR(40) NOT NULL,
  `committed_at` DATETIME(6) NOT NULL,
  `file_count` INT NULL,
  `hf_repo_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `last_read_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `message` TEXT NULL,
  `parent_sha` TEXT NULL,
  `source` TEXT NOT NULL,
  `total_bytes` BIGINT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_hf_commits_hf_repo_id_commit_sha` (`hf_repo_id`, `commit_sha`),
  KEY `ix_hf_commits_hf_repo_id_committed_at_desc_id_desc` (`hf_repo_id`, `committed_at` DESC, `id` DESC),
  KEY `ix_hf_commits_last_read_at` (`last_read_at`),
  CONSTRAINT `hf_commits_counts_check` CHECK ((((`file_count` IS NULL) OR (`file_count` >= 0)) AND ((`total_bytes` IS NULL) OR (`total_bytes` >= 0)))),
  CONSTRAINT `hf_commits_parent_check` CHECK (((`parent_sha` IS NULL) OR REGEXP_LIKE(`parent_sha`, '^[0-9a-f]{40}\\z', 'cn'))),
  CONSTRAINT `hf_commits_sha_check` CHECK (REGEXP_LIKE(`commit_sha`, '^[0-9a-f]{40}\\z', 'cn')),
  CONSTRAINT `hf_commits_source_check` CHECK ((`source` IN ('upstream', 'hosted', 'promoted')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `hf_files` (
  `cached` TINYINT(1) NOT NULL DEFAULT 0,
  `commit_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `git_blob_id` TEXT NULL,
  `lfs` TINYINT(1) NOT NULL DEFAULT 0,
  `path` VARCHAR(512) NOT NULL,
  `pickle_flag` TINYINT(1) NOT NULL DEFAULT 0,
  `sha256` VARCHAR(64) NULL,
  `size` BIGINT NOT NULL,
  PRIMARY KEY (`commit_id`, `path`),
  KEY `ix_hf_files_sha256` (`sha256`),
  CONSTRAINT `hf_files_sha256_check` CHECK (((`sha256` IS NULL) OR REGEXP_LIKE(`sha256`, '^[0-9a-f]{64}\\z', 'cn'))),
  CONSTRAINT `hf_files_size_check` CHECK ((`size` >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `hf_refs` (
  `checked_at` DATETIME(6) NOT NULL,
  `commit_sha` TEXT NOT NULL,
  `expires_at` DATETIME(6) NOT NULL,
  `hf_repo_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `ref_kind` VARCHAR(8) NOT NULL,
  `ref_name` VARCHAR(255) NOT NULL,
  PRIMARY KEY (`hf_repo_id`, `ref_kind`, `ref_name`),
  KEY `ix_hf_refs_expires_at` (`expires_at`),
  CONSTRAINT `hf_refs_kind_check` CHECK ((`ref_kind` IN ('branch', 'tag'))),
  CONSTRAINT `hf_refs_sha_check` CHECK (REGEXP_LIKE(`commit_sha`, '^[0-9a-f]{40}\\z', 'cn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `hf_repos` (
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
