  KEY `ix_hosted_group_idempotency_group_id` (`group_id`),
  CONSTRAINT `hosted_group_idempotency_key_check` CHECK (((CHAR_LENGTH(`key`) >= 1) AND (CHAR_LENGTH(`key`) <= 128)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `hosted_group_members` (
  `group_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `position` INT NOT NULL,
  `repository_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  PRIMARY KEY (`group_id`, `position`),
  UNIQUE KEY `uq_hosted_group_members_group_id_repository_id` (`group_id`, `repository_id`),
  KEY `ix_hosted_group_members_repository_id` (`repository_id`),
  CONSTRAINT `hosted_group_members_position_check` CHECK ((`position` >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `hosted_groups` (
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `format` TEXT NOT NULL,
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `version` BIGINT NOT NULL DEFAULT 1,
  `visibility` VARCHAR(255) NOT NULL DEFAULT 'private',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_hosted_groups_name` (`name`),
  KEY `ix_hosted_groups_visibility_name` (`visibility`, `name`),
  CONSTRAINT `hosted_groups_format_check` CHECK ((`format` IN ('raw', 'oci', 'maven', 'conan', 'npm', 'pypi', 'go', 'apt', 'cargo', 'nuget', 'helm', 'huggingface'))),
  CONSTRAINT `hosted_groups_name_check` CHECK (REGEXP_LIKE(`name`, '^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\\z', 'cn')),
  CONSTRAINT `hosted_groups_visibility_check` CHECK ((`visibility` IN ('private', 'authenticated', 'public')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `hosted_repositories` (
  `allowed_hosts` JSON NOT NULL DEFAULT (CAST('[]' AS JSON)),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `egress_proxy` JSON NULL,
  `endpoint` TEXT NOT NULL DEFAULT (''),
  `format` TEXT NOT NULL,
  `grants_version` BIGINT NOT NULL DEFAULT 1,
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `maven_strict_publication` TINYINT(1) NOT NULL DEFAULT 0,
  `name` VARCHAR(255) NOT NULL,
  `oci_bearer` JSON NULL,
  `raw_layout` TEXT NOT NULL DEFAULT ('path'),
  `raw_strict` TINYINT(1) NOT NULL DEFAULT 0,
  `repo_type` TEXT NOT NULL DEFAULT ('hosted'),
  `seal_mode` TEXT NOT NULL DEFAULT ('explicit'),
  `state` TEXT NOT NULL DEFAULT ('active'),
  `upstream_auth` JSON NULL,
  `version` BIGINT NOT NULL DEFAULT 1,
  `visibility` VARCHAR(255) NOT NULL DEFAULT 'private',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_hosted_repositories_name` (`name`),
  KEY `ix_hosted_repositories_created_at_id` (`created_at`, `id`),
  KEY `ix_hosted_repositories_visibility_name` (`visibility`, `name`),
  CONSTRAINT `hosted_repositories_format_check` CHECK ((`format` IN ('raw', 'oci', 'maven', 'conan', 'npm', 'pypi', 'go', 'apt', 'cargo', 'nuget', 'helm', 'rubygems', 'huggingface'))),
  CONSTRAINT `hosted_repositories_maven_strict_publication_check` CHECK (((NOT `maven_strict_publication`) OR ((`format` = 'maven') AND (`repo_type` = 'hosted')))),
  CONSTRAINT `hosted_repositories_name_check` CHECK (REGEXP_LIKE(`name`, '^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\\z', 'cn')),
  CONSTRAINT `hosted_repositories_raw_layout_check` CHECK ((`raw_layout` IN ('path', 'versioned'))),
  CONSTRAINT `hosted_repositories_raw_layout_shape_check` CHECK (((((`raw_layout` = 'path') AND (`seal_mode` = 'explicit')) AND (NOT `raw_strict`)) OR (((`raw_layout` = 'versioned') AND (`format` = 'raw')) AND (`repo_type` = 'hosted')))),
  CONSTRAINT `hosted_repositories_repo_shape_check` CHECK ((((`repo_type` = 'hosted') AND (`endpoint` = '')) OR ((`repo_type` = 'proxy') AND (`endpoint` <> '')))),
  CONSTRAINT `hosted_repositories_repo_type_check` CHECK ((`repo_type` IN ('hosted', 'proxy'))),
  CONSTRAINT `hosted_repositories_seal_mode_check` CHECK ((`seal_mode` IN ('explicit', 'idle'))),
  CONSTRAINT `hosted_repositories_state_check` CHECK ((`state` IN ('active', 'deleting', 'deleted'))),
  CONSTRAINT `hosted_repositories_visibility_check` CHECK ((`visibility` IN ('private', 'authenticated', 'public')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `hosted_repository_idempotency` (
  `actor` VARCHAR(255) NOT NULL,
  `expires_at` DATETIME(6) NOT NULL,
  `key` VARCHAR(255) NOT NULL,
  `payload_hash` TEXT NOT NULL,
  `repository_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `target` VARCHAR(255) NOT NULL,
  PRIMARY KEY (`actor`, `target`, `key`),
  KEY `ix_hosted_repository_idempotency_expires_at` (`expires_at`),
  KEY `ix_hosted_repository_idempotency_repository_id` (`repository_id`),
  CONSTRAINT `hosted_repository_idempotency_key_check` CHECK (((CHAR_LENGTH(`key`) >= 1) AND (CHAR_LENGTH(`key`) <= 128)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `identity_provider_scim_tokens` (
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `expires_at` DATETIME(6) NOT NULL,
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `name` TEXT NOT NULL,
  `provider_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `revoked_at` DATETIME(6) NULL,
  `secret_hash` VARCHAR(128) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_identity_provider_scim_tokens_secret_hash` (`secret_hash`),
  KEY `ix_identity_provider_scim_tokens_provider_id_id` (`provider_id`, `id`),
  CONSTRAINT `identity_provider_scim_tokens_name_check` CHECK (((CHAR_LENGTH(TRIM(`name`)) >= 1) AND (CHAR_LENGTH(TRIM(`name`)) <= 128)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `identity_providers` (
  `attribute_mapping` JSON NOT NULL DEFAULT (CAST('{}' AS JSON)),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `display_name` TEXT NOT NULL,
  `email_linking_enabled` TINYINT(1) NOT NULL DEFAULT 0,
  `enabled` TINYINT(1) NOT NULL DEFAULT 0,
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `jit_default_role` TEXT NOT NULL DEFAULT ('none'),
  `kind` TEXT NOT NULL,
  `provisioning_mode` TEXT NOT NULL DEFAULT ('disabled'),
  `secrets_sealed` TEXT NULL,
  `settings` JSON NOT NULL DEFAULT (CAST('{}' AS JSON)),
  `slug` VARCHAR(128) NOT NULL,
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `version` BIGINT NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_identity_providers_slug` (`slug`),
  CONSTRAINT `identity_providers_attribute_mapping_check` CHECK ((JSON_TYPE(`attribute_mapping`) = 'OBJECT')),
  CONSTRAINT `identity_providers_display_name_check` CHECK (((CHAR_LENGTH(TRIM(`display_name`)) >= 1) AND (CHAR_LENGTH(TRIM(`display_name`)) <= 120))),
  CONSTRAINT `identity_providers_jit_default_role_check` CHECK ((`jit_default_role` IN ('none', 'member'))),
  CONSTRAINT `identity_providers_kind_check` CHECK ((`kind` IN ('oidc', 'saml'))),
  CONSTRAINT `identity_providers_provisioning_mode_check` CHECK ((`provisioning_mode` IN ('disabled', 'jit', 'scim_only'))),
  CONSTRAINT `identity_providers_settings_check` CHECK ((JSON_TYPE(`settings`) = 'OBJECT')),
  CONSTRAINT `identity_providers_slug_check` CHECK (REGEXP_LIKE(`slug`, '^[a-z0-9][a-z0-9-]{1,62}\\z', 'cn')),
  CONSTRAINT `identity_providers_version_check` CHECK ((`version` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `installation_repository_presets` (
  `catalog_version` TEXT NOT NULL,
  `finished_at` DATETIME(6) NULL,
  `groups_created` INT NOT NULL DEFAULT 0,
  `repositories_created` INT NOT NULL DEFAULT 0,
  `singleton` TINYINT(1) NOT NULL DEFAULT 1,
  `state` TEXT NOT NULL,
  PRIMARY KEY (`singleton`),
  CONSTRAINT `installation_repository_presets_groups_created_check` CHECK ((`groups_created` >= 0)),
  CONSTRAINT `installation_repository_presets_repositories_created_check` CHECK ((`repositories_created` >= 0)),
  CONSTRAINT `installation_repository_presets_singleton_check` CHECK ((`singleton` <> 0)),
  CONSTRAINT `installation_repository_presets_state_check` CHECK ((`state` IN ('pending', 'applied', 'skipped_existing')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `instance_identity` (
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
