  PRIMARY KEY (`singleton`),
  CONSTRAINT `instance_identity_singleton_check` CHECK ((`singleton` <> 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `lifecycle_jobs` (
  `attempts` INT NOT NULL DEFAULT 0,
  `completed_at` DATETIME(6) NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `idempotency_key` VARCHAR(255) NOT NULL,
  `kind` VARCHAR(32) NOT NULL,
  `last_error` TEXT NOT NULL DEFAULT (''),
  `lease_expires_at` DATETIME(6) NULL,
  `lease_token` TEXT NOT NULL DEFAULT (''),
  `max_attempts` INT NOT NULL DEFAULT 3,
  `next_attempt_at` DATETIME(6) NULL,
  `payload` JSON NOT NULL DEFAULT (CAST('{}' AS JSON)),
  `progress_current` INT NOT NULL DEFAULT 0,
  `progress_message` TEXT NOT NULL DEFAULT (''),
  `progress_total` INT NOT NULL DEFAULT 0,
  `repository_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `started_at` DATETIME(6) NULL,
  `state` TEXT NOT NULL,
  `actionable` TINYINT(1) GENERATED ALWAYS AS (IF((`state` IN ('pending', 'retrying')), 1, 0)) VIRTUAL NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_lifecycle_jobs_repository_id_kind_idempotency_key` (`repository_id`, `kind`, `idempotency_key`),
  KEY `ix_lifecycle_jobs_created_at_desc_id_desc` (`created_at` DESC, `id` DESC),
  KEY `ix_lifecycle_jobs_repository_id_created_at_desc_id_desc` (`repository_id`, `created_at` DESC, `id` DESC),
  KEY `ix_lifecycle_jobs_actionable_idx` (`actionable`, `next_attempt_at`, `created_at`),
  KEY `ix_lifecycle_jobs_kind_actionable_idx` (`actionable`, `kind`, `next_attempt_at`),
  KEY `ix_lifecycle_jobs_lease_idx` (`lease_expires_at`),
  KEY `ix_lifecycle_jobs_pending_idx` (`created_at`),
  KEY `ix_lifecycle_jobs_retention_idx` (`completed_at`),
  KEY `ix_lifecycle_jobs_running_repository_idx` (`repository_id`),
  CONSTRAINT `lifecycle_jobs_attempts_check` CHECK ((`attempts` >= 0)),
  CONSTRAINT `lifecycle_jobs_kind_check` CHECK ((`kind` IN ('retention', 'promotion', 'replication', 'reclaim', 'intelligence', 'scan'))),
  CONSTRAINT `lifecycle_jobs_max_attempts_check` CHECK (((`max_attempts` >= 1) AND (`max_attempts` <= 20))),
  CONSTRAINT `lifecycle_jobs_progress_current_check` CHECK ((`progress_current` >= 0)),
  CONSTRAINT `lifecycle_jobs_progress_total_check` CHECK ((`progress_total` >= 0)),
