  CONSTRAINT `native_cargo_proxy_indexes_check` CHECK (((((`status` = 200) AND (LENGTH(`body`) > 0)) OR (((`status` = 200) AND (`body_digest` IS NOT NULL)) AND (LENGTH(`body`) = 0))) OR ((`status` <> 200) AND (LENGTH(`body`) = 0)))),
