  `credential_id` TEXT NOT NULL DEFAULT (''),
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `lease_fence` BIGINT NOT NULL DEFAULT 0,
  `lease_owner` TEXT NOT NULL DEFAULT (''),
  `lease_token` TEXT NOT NULL DEFAULT (''),
  `lease_until` DATETIME(6) NULL,
  `plan_digest` TEXT NOT NULL,
  `source_repository_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `state` TEXT NOT NULL,
  `target_repository_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `version` BIGINT NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  KEY `ix_native_nuget_replication_jobs_source_repository_id` (`source_repository_id`),
  KEY `ix_native_nuget_replication_jobs_target_repository_id` (`target_repository_id`),
  KEY `ix_native_nuget_replication_claim` (`created_at`, `id`),
  CONSTRAINT `native_nuget_replication_jobs_actor_check` CHECK (((CHAR_LENGTH(`actor`) >= 1) AND (CHAR_LENGTH(`actor`) <= 512))),
  CONSTRAINT `native_nuget_replication_jobs_actor_kind_check` CHECK ((`actor_kind` IN ('static_admin', 'static_resolver', 'local_session', 'oidc', 'api_key', 'service_account_credential', 'workload_federation'))),
  CONSTRAINT `native_nuget_replication_jobs_check` CHECK ((`source_repository_id` <> `target_repository_id`)),
  CONSTRAINT `native_nuget_replication_jobs_check1` CHECK (((`state` = 'running') = (((`lease_owner` <> '') AND (`lease_token` <> '')) AND (`lease_until` IS NOT NULL)))),
  CONSTRAINT `native_nuget_replication_jobs_lease_fence_check` CHECK ((`lease_fence` >= 0)),
  CONSTRAINT `native_nuget_replication_jobs_plan_digest_check` CHECK (REGEXP_LIKE(`plan_digest`, '^sha256:[0-9a-f]{64}\\z', 'cn')),
  CONSTRAINT `native_nuget_replication_jobs_state_check` CHECK ((`state` IN ('queued', 'running', 'succeeded', 'failed'))),
  CONSTRAINT `native_nuget_replication_jobs_version_check` CHECK ((`version` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

