  CONSTRAINT `native_pypi_files_digest_check` CHECK (REGEXP_LIKE(`digest`, '^sha256:[0-9a-f]{64}\\z', 'cn')),
  CONSTRAINT `native_pypi_files_project_check` CHECK (REGEXP_LIKE(`project`, '^[a-z0-9]([a-z0-9-]{0,253}[a-z0-9])?\\z', 'cn')),
