  CONSTRAINT `oci_bound_objects_owner_check` CHECK (REGEXP_LIKE(`owner`, '^[a-f0-9]{64}\\z', 'cn')),
  CONSTRAINT `oci_bound_objects_source_version_check` CHECK ((`source_version` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `oci_discovery_snapshots` (
  `body_digest` TEXT NULL,
  `body_key` VARCHAR(512) NULL,
  `body_size` BIGINT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `expires_at` DATETIME(6) NOT NULL,
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `kind` TEXT NOT NULL,
  `owner` VARCHAR(64) NOT NULL,
  `payload` JSON NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_oci_discovery_snapshots_owner_expires_at` (`owner`, `expires_at`),
  KEY `ix_oci_discovery_snapshots_body_key_idx` (`body_key`),
  CONSTRAINT `oci_discovery_snapshots_body_ref_check` CHECK (((((`body_digest` IS NULL) AND (`body_size` IS NULL)) AND (`body_key` IS NULL)) OR ((((`body_digest` IS NOT NULL) AND (`body_size` IS NOT NULL)) AND (`body_key` IS NOT NULL)) AND (`body_size` >= 0)))),
  CONSTRAINT `oci_discovery_snapshots_kind_check` CHECK ((`kind` IN ('catalog', 'referrers')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `oci_group_members` (
  `allowed_hosts` JSON NOT NULL DEFAULT (CAST('[]' AS JSON)),
