  `group_name` VARCHAR(255) NOT NULL,
  `member_type` TEXT NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `position` INT NOT NULL,
  `repository_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  PRIMARY KEY (`group_name`, `position`),
  UNIQUE KEY `uq_oci_group_members_group_name_name` (`group_name`, `name`),
  KEY `ix_oci_group_members_repository_id` (`repository_id`),
  CONSTRAINT `oci_group_members_member_type_check` CHECK ((`member_type` IN ('hosted', 'proxy'))),
  CONSTRAINT `oci_group_members_position_check` CHECK ((`position` >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `oci_groups` (
  `anonymous` TINYINT(1) NOT NULL DEFAULT 0,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `enabled` TINYINT(1) NOT NULL DEFAULT 1,
