  `owner` VARCHAR(64) NOT NULL,
  `payload` JSON NOT NULL,
  `scope` VARCHAR(128) NOT NULL,
  `source_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `source_version` BIGINT NOT NULL,
  `subject` VARCHAR(144) NOT NULL,
  PRIMARY KEY (`scope`, `owner`, `image`, `subject`),
  KEY `ix_oci_subject_bindings_source_id` (`source_id`),
  CONSTRAINT `oci_subject_bindings_owner_check` CHECK (REGEXP_LIKE(`owner`, '^[a-f0-9]{64}\\z', 'cn')),
  CONSTRAINT `oci_subject_bindings_source_version_check` CHECK ((`source_version` > 0)),
  CONSTRAINT `oci_subject_bindings_subject_check` CHECK (REGEXP_LIKE(`subject`, '^sha256:[a-f0-9]{64}\\z', 'cn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `promotion_rules` (
  `approval` JSON NULL,
  `conditions` JSON NOT NULL DEFAULT (CAST('{}' AS JSON)),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `created_by` TEXT NOT NULL,
  `enabled` TINYINT(1) NOT NULL DEFAULT 1,
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `match` JSON NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `remote_instance_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  `remote_repository` TEXT NULL,
  `run_as_service_account_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `schedule` JSON NULL,
  `source_repository_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `target_kind` TEXT NOT NULL,
  `target_repository_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_by` TEXT NOT NULL,
  `version` BIGINT NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_promotion_rules_name` (`name`),
  KEY `ix_promotion_rules_remote_instance_id` (`remote_instance_id`),
  KEY `ix_promotion_rules_run_as_service_account_id` (`run_as_service_account_id`),
  KEY `ix_promotion_rules_source_repository_id_enabled` (`source_repository_id`, `enabled`),
  KEY `ix_promotion_rules_target_repository_id` (`target_repository_id`),
  KEY `ix_promotion_rules_name_bytes_idx` (`name`),
  CONSTRAINT `promotion_rules_actor_check` CHECK (((((CHAR_LENGTH(`created_by`) >= 1) AND (CHAR_LENGTH(`created_by`) <= 255)) AND (CHAR_LENGTH(`updated_by`) >= 1)) AND (CHAR_LENGTH(`updated_by`) <= 255))),
  CONSTRAINT `promotion_rules_approval_check` CHECK (((`approval` IS NULL) OR (JSON_TYPE(`approval`) = 'OBJECT'))),
  CONSTRAINT `promotion_rules_conditions_check` CHECK ((JSON_TYPE(`conditions`) = 'OBJECT')),
  CONSTRAINT `promotion_rules_match_check` CHECK ((JSON_TYPE(`match`) = 'OBJECT')),
  CONSTRAINT `promotion_rules_name_check` CHECK (((CHAR_LENGTH(`name`) >= 1) AND (CHAR_LENGTH(`name`) <= 128))),
  CONSTRAINT `promotion_rules_schedule_check` CHECK (((`schedule` IS NULL) OR (JSON_TYPE(`schedule`) = 'OBJECT'))),
  CONSTRAINT `promotion_rules_version_check` CHECK ((`version` >= 1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `public_access_policy` (
  `enabled` TINYINT(1) NOT NULL DEFAULT 0,
  `singleton` TINYINT(1) NOT NULL DEFAULT 1,
  `version` BIGINT NOT NULL DEFAULT 1,
  PRIMARY KEY (`singleton`),
  CONSTRAINT `public_access_policy_singleton_check` CHECK ((`singleton` <> 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `raw_group_members` (
  `allowed_hosts` JSON NOT NULL DEFAULT (CAST('[]' AS JSON)),
  `endpoint` TEXT NOT NULL,
  `group_name` VARCHAR(255) NOT NULL,
  `member_type` TEXT NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `position` INT NOT NULL,
  `repository_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  PRIMARY KEY (`group_name`, `position`),
  UNIQUE KEY `uq_raw_group_members_group_name_name` (`group_name`, `name`),
  KEY `ix_raw_group_members_repository_id` (`repository_id`),
  CONSTRAINT `raw_group_members_member_type_check` CHECK ((`member_type` IN ('hosted', 'proxy'))),
  CONSTRAINT `raw_group_members_position_check` CHECK ((`position` >= 0)),
  CONSTRAINT `raw_group_proxy_allowlist_required` CHECK (((`member_type` <> 'proxy') OR (JSON_LENGTH(`allowed_hosts`) > 0)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `raw_groups` (
  `anonymous` TINYINT(1) NOT NULL DEFAULT 0,
  `cache_quota_bytes` BIGINT NOT NULL DEFAULT 1073741824,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `enabled` TINYINT(1) NOT NULL DEFAULT 1,
  `name` VARCHAR(255) NOT NULL,
  PRIMARY KEY (`name`),
  CONSTRAINT `raw_groups_cache_quota_bytes_check` CHECK ((`cache_quota_bytes` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `remote_instances` (
  `audience` TEXT NOT NULL DEFAULT (''),
  `auth_kind` TEXT NOT NULL,
  `base_url` TEXT NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `instance_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `last_checked_at` DATETIME(6) NULL,
  `name` VARCHAR(255) NOT NULL,
  `state` TEXT NOT NULL DEFAULT ('active'),
  `token_sealed` TEXT NULL,
  `trust_evidence` TINYINT(1) NOT NULL DEFAULT 0,
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `version` BIGINT NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_remote_instances_name` (`name`),
  KEY `ix_remote_instances_name_bytes_idx` (`name`),
  CONSTRAINT `remote_instances_audience_check` CHECK (((CHAR_LENGTH(`audience`) <= 512) AND ((`auth_kind` <> 'workload_identity') OR (`audience` <> '')))),
  CONSTRAINT `remote_instances_auth_kind_check` CHECK ((`auth_kind` IN ('workload_identity', 'static_token'))),
  CONSTRAINT `remote_instances_base_url_check` CHECK (((CHAR_LENGTH(`base_url`) >= 1) AND (CHAR_LENGTH(`base_url`) <= 2048))),
  CONSTRAINT `remote_instances_name_check` CHECK (((CHAR_LENGTH(`name`) >= 1) AND (CHAR_LENGTH(`name`) <= 128))),
  CONSTRAINT `remote_instances_state_check` CHECK ((`state` IN ('active', 'unreachable', 'disabled'))),
  CONSTRAINT `remote_instances_token_check` CHECK (((((`auth_kind` = 'static_token') AND (`token_sealed` IS NOT NULL)) AND (`token_sealed` <> '')) OR ((`auth_kind` = 'workload_identity') AND (`token_sealed` IS NULL)))),
  CONSTRAINT `remote_instances_version_check` CHECK ((`version` >= 1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `replication_checkpoints` (
  `attempts` INT NOT NULL DEFAULT 0,
  `byte_offset` BIGINT NOT NULL DEFAULT 0,
  `digest` TEXT NOT NULL,
  `last_error` TEXT NOT NULL DEFAULT (''),
  `object_key` VARCHAR(512) NOT NULL,
  `plan_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `size` BIGINT NOT NULL,
  `source_object_key` TEXT NOT NULL,
  `state` VARCHAR(255) NOT NULL DEFAULT 'pending',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `verified_at` DATETIME(6) NULL,
  PRIMARY KEY (`plan_id`, `object_key`),
  KEY `ix_replication_checkpoints_plan_id_state_updated_at` (`plan_id`, `state`, `updated_at`),
  KEY `ix_replication_checkpoints_updated_at` (`updated_at`),
  CONSTRAINT `replication_checkpoints_attempts_check` CHECK ((`attempts` >= 0)),
  CONSTRAINT `replication_checkpoints_byte_offset_check` CHECK ((`byte_offset` >= 0)),
  CONSTRAINT `replication_checkpoints_digest_check` CHECK (REGEXP_LIKE(`digest`, '^sha256:[0-9a-f]{64}\\z', 'cn')),
  CONSTRAINT `replication_checkpoints_size_check` CHECK ((`size` >= 0)),
  CONSTRAINT `replication_checkpoints_state_check` CHECK ((`state` IN ('pending', 'copying', 'verified', 'failed')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `replication_plans` (
  `apt_target_suite` TEXT NOT NULL DEFAULT (''),
  `attempts` INT NOT NULL DEFAULT 0,
  `completed_at` DATETIME(6) NULL,
  `coordinate` TEXT NOT NULL DEFAULT (''),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `digest` TEXT NOT NULL DEFAULT (''),
  `format` TEXT NOT NULL,
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `idempotency_key` VARCHAR(255) NOT NULL,
  `last_error` TEXT NOT NULL DEFAULT (''),
  `lease_expires_at` DATETIME(6) NULL,
  `lease_token` TEXT NULL,
  `max_attempts` INT NOT NULL DEFAULT 3,
  `next_attempt_at` DATETIME(6) NULL DEFAULT CURRENT_TIMESTAMP(6),
  `source_repository_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `started_at` DATETIME(6) NULL,
  `state` TEXT NOT NULL DEFAULT ('pending'),
  `target_repository_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_replication_plans_target_repository_id_idempotency_key` (`target_repository_id`, `idempotency_key`),
  KEY `ix_replication_plans_source_repository_id` (`source_repository_id`),
  KEY `ix_replication_plans_claim_idx` (`created_at`),
  KEY `ix_replication_plans_retention_idx` (`completed_at`),
  KEY `ix_replication_plans_retry_idx` (`next_attempt_at`, `created_at`),
  CONSTRAINT `replication_apt_target_suite_format` CHECK (((`apt_target_suite` = '') OR (((`format` = 'apt') AND REGEXP_LIKE(`apt_target_suite`, '^[a-z0-9][a-z0-9.+-]*\\z', 'cn')) AND (CHAR_LENGTH(`apt_target_suite`) <= 128)))),
  CONSTRAINT `replication_plans_artifact_identity_check` CHECK ((((`coordinate` = '') AND (`digest` = '')) OR ((`coordinate` <> '') AND REGEXP_LIKE(`digest`, '^sha256:[a-f0-9]{64}\\z', 'cn')))),
  CONSTRAINT `replication_plans_attempts_check` CHECK ((`attempts` >= 0)),
  CONSTRAINT `replication_plans_format_check` CHECK ((`format` IN ('maven', 'oci', 'raw', 'conan', 'npm', 'pypi', 'go', 'apt', 'cargo'))),
  CONSTRAINT `replication_plans_max_attempts_check` CHECK (((`max_attempts` >= 1) AND (`max_attempts` <= 10))),
  CONSTRAINT `replication_plans_state_check` CHECK ((`state` IN ('pending', 'running', 'completed', 'failed', 'cancelled')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `repository_capacity_quotas` (
  `quota_bytes` BIGINT NOT NULL DEFAULT 0,
  `repository_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  PRIMARY KEY (`repository_id`),
  CONSTRAINT `repository_capacity_quotas_quota_bytes_check` CHECK ((`quota_bytes` >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `repository_grant_sets` (
  `repository_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `version` BIGINT NOT NULL DEFAULT 1,
  PRIMARY KEY (`repository_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `repository_grants` (
  `principal` VARCHAR(255) NOT NULL,
  `repository_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `resource_prefix` VARCHAR(480) NOT NULL DEFAULT '',
  `scopes` JSON NOT NULL,
  PRIMARY KEY (`repository_id`, `principal`, `resource_prefix`),
  KEY `ix_repository_grants_principal_idx` (`principal`, `repository_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `repository_quarantine_read_policies` (
  `enabled` TINYINT(1) NOT NULL DEFAULT 0,
  `repository_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `version` BIGINT NOT NULL DEFAULT 1,
  PRIMARY KEY (`repository_id`),
  CONSTRAINT `repository_quarantine_read_policies_version_check` CHECK ((`version` >= 1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `repository_quota_alert_events` (
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `delivery_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  `episode_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `notification_code` TEXT NOT NULL,
  `rule_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `rule_version` BIGINT NOT NULL,
  `scenario` VARCHAR(64) NOT NULL,
  `sequence` BIGINT NOT NULL,
  `snapshot` JSON NOT NULL,
  `target_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `target_version` BIGINT NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_repository_quota_alert_events_episode_id_scenario` (`episode_id`, `scenario`),
  UNIQUE KEY `uq_repository_quota_alert_events_rule_id_sequence` (`rule_id`, `sequence`),
  KEY `ix_repository_quota_alert_events_created_at` (`created_at`),
  KEY `ix_repository_quota_alert_events_delivery_id` (`delivery_id`),
  KEY `ix_repository_quota_alert_events_target_id` (`target_id`),
  CONSTRAINT `repository_quota_alert_events_notification_code_check` CHECK ((`notification_code` IN ('queued', 'queue_full', 'email_disabled', 'encryption_key_unavailable', 'target_disabled', 'target_changed', 'target_unavailable'))),
  CONSTRAINT `repository_quota_alert_events_scenario_check` CHECK ((`scenario` IN ('warning', 'critical', 'resolved'))),
  CONSTRAINT `repository_quota_alert_events_sequence_check` CHECK ((`sequence` > 0)),
  CONSTRAINT `repository_quota_alert_events_snapshot_check` CHECK ((LENGTH(`snapshot`) <= 8192))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `repository_quota_alert_rules` (
  `active_episode_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `deleted` TINYINT(1) NOT NULL DEFAULT 0,
  `enabled` TINYINT(1) NOT NULL DEFAULT 0,
  `evaluated_at` DATETIME(6) NULL,
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `last_event_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  `next_evaluate_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `policy` JSON NOT NULL,
  `repository_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `sequence` BIGINT NOT NULL DEFAULT 0,
  `state` JSON NOT NULL,
  `state_version` BIGINT NOT NULL DEFAULT 1,
  `target_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `target_version` BIGINT NOT NULL,
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `version` BIGINT NOT NULL DEFAULT 1,
  `live_repository_quota_rule_scope` TINYINT(1) GENERATED ALWAYS AS (IF((NOT `deleted`), 1, NULL)) VIRTUAL NULL,
  PRIMARY KEY (`id`),
  KEY `ix_repository_quota_alert_rules_target_id` (`target_id`),
  KEY `ix_repository_quota_rule_due` (`next_evaluate_at`, `id`),
  UNIQUE KEY `uq_repository_quota_rule_scope` (`repository_id`, `live_repository_quota_rule_scope`),
  CONSTRAINT `repository_quota_alert_rules_check` CHECK (((NOT `deleted`) OR (NOT `enabled`))),
  CONSTRAINT `repository_quota_alert_rules_policy_check` CHECK (((JSON_TYPE(`policy`) = 'OBJECT') AND (LENGTH(`policy`) <= 2048))),
  CONSTRAINT `repository_quota_alert_rules_policy_check1` CHECK (JSON_CONTAINS_PATH(`policy`, 'all', '$."warningBasisPoints"', '$."criticalBasisPoints"', '$."recoveryBelowBasisPoints"', '$."warningForSeconds"', '$."criticalForSeconds"', '$."recoveryForSeconds"', '$."maxSampleAgeSeconds"')),
  CONSTRAINT `repository_quota_alert_rules_policy_check2` CHECK (((((CAST(JSON_UNQUOTE(JSON_EXTRACT(`policy`, '$."recoveryBelowBasisPoints"')) AS SIGNED) > 0) AND (CAST(JSON_UNQUOTE(JSON_EXTRACT(`policy`, '$."recoveryBelowBasisPoints"')) AS SIGNED) < CAST(JSON_UNQUOTE(JSON_EXTRACT(`policy`, '$."warningBasisPoints"')) AS SIGNED))) AND (CAST(JSON_UNQUOTE(JSON_EXTRACT(`policy`, '$."warningBasisPoints"')) AS SIGNED) < CAST(JSON_UNQUOTE(JSON_EXTRACT(`policy`, '$."criticalBasisPoints"')) AS SIGNED))) AND (CAST(JSON_UNQUOTE(JSON_EXTRACT(`policy`, '$."criticalBasisPoints"')) AS SIGNED) <= 10000))),
  CONSTRAINT `repository_quota_alert_rules_policy_check3` CHECK (((((CAST(JSON_UNQUOTE(JSON_EXTRACT(`policy`, '$."warningForSeconds"')) AS SIGNED) >= 1) AND (CAST(JSON_UNQUOTE(JSON_EXTRACT(`policy`, '$."warningForSeconds"')) AS SIGNED) <= 86400)) AND ((CAST(JSON_UNQUOTE(JSON_EXTRACT(`policy`, '$."criticalForSeconds"')) AS SIGNED) >= 1) AND (CAST(JSON_UNQUOTE(JSON_EXTRACT(`policy`, '$."criticalForSeconds"')) AS SIGNED) <= 86400))) AND ((CAST(JSON_UNQUOTE(JSON_EXTRACT(`policy`, '$."recoveryForSeconds"')) AS SIGNED) >= 1) AND (CAST(JSON_UNQUOTE(JSON_EXTRACT(`policy`, '$."recoveryForSeconds"')) AS SIGNED) <= 86400)))),
  CONSTRAINT `repository_quota_alert_rules_policy_check4` CHECK (((CAST(JSON_UNQUOTE(JSON_EXTRACT(`policy`, '$."maxSampleAgeSeconds"')) AS SIGNED) >= 30) AND (CAST(JSON_UNQUOTE(JSON_EXTRACT(`policy`, '$."maxSampleAgeSeconds"')) AS SIGNED) <= 3600))),
  CONSTRAINT `repository_quota_alert_rules_sequence_check` CHECK ((`sequence` >= 0)),
  CONSTRAINT `repository_quota_alert_rules_state_check` CHECK (((JSON_TYPE(`state`) = 'OBJECT') AND (LENGTH(`state`) <= 4096)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `repository_request_rollup` (
  `bucket_start` DATETIME(6) NOT NULL,
  `bytes` BIGINT NOT NULL DEFAULT 0,
  `outcome` SMALLINT NOT NULL,
  `repository_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `requests` BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY (`repository_id`, `bucket_start`, `outcome`),
  KEY `ix_repository_request_rollup_bucket_start` (`bucket_start`),
  CONSTRAINT `repository_request_rollup_counts_check` CHECK (((`requests` >= 0) AND (`bytes` >= 0))),
  CONSTRAINT `repository_request_rollup_outcome_check` CHECK (((`outcome` >= 0) AND (`outcome` <= 6)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `repository_retention_policies` (
  `coordinate_patterns` JSON NOT NULL DEFAULT (CAST('[]' AS JSON)),
  `enabled` TINYINT(1) NOT NULL DEFAULT 0,
  `keep_days` INT NOT NULL,
  `keep_downloaded_days` INT NOT NULL DEFAULT 0,
  `maximum_versions` INT NOT NULL DEFAULT 0,
  `minimum_versions` INT NOT NULL,
  `protected_patterns` JSON NOT NULL DEFAULT (CAST('[]' AS JSON)),
  `repository_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `snapshot_keep_days` INT NOT NULL DEFAULT 30,
  `version` BIGINT NOT NULL DEFAULT 1,
  PRIMARY KEY (`repository_id`),
  CONSTRAINT `repository_retention_policies_keep_days_check` CHECK ((`keep_days` >= 1)),
  CONSTRAINT `repository_retention_policies_maximum_versions_check` CHECK ((`maximum_versions` >= 0)),
  CONSTRAINT `repository_retention_policies_minimum_versions_check` CHECK ((`minimum_versions` >= 1)),
  CONSTRAINT `repository_retention_policies_snapshot_keep_days_check` CHECK ((`snapshot_keep_days` >= 1)),
  CONSTRAINT `repository_retention_versions_valid` CHECK (((`maximum_versions` = 0) OR (`maximum_versions` >= `minimum_versions`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `repository_security_policies` (
  `allowed_licenses` JSON NOT NULL DEFAULT (CAST('[]' AS JSON)),
  `auto_scan_on_publish` TINYINT(1) NOT NULL DEFAULT 0,
  `enabled` TINYINT(1) NOT NULL DEFAULT 0,
  `fail_on_scan_error` TINYINT(1) NOT NULL DEFAULT 1,
  `max_allowed_severity` TEXT NOT NULL DEFAULT ('critical'),
  `repository_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `require_provenance` TINYINT(1) NOT NULL DEFAULT 0,
  `require_sbom` TINYINT(1) NOT NULL DEFAULT 0,
  `require_signature` TINYINT(1) NOT NULL DEFAULT 0,
  `require_verified_signature` TINYINT(1) NOT NULL DEFAULT 0,
  `require_vulnerability_scan` TINYINT(1) NOT NULL DEFAULT 0,
  `version` BIGINT NOT NULL DEFAULT 1,
  PRIMARY KEY (`repository_id`),
  CONSTRAINT `repository_security_policies_max_allowed_severity_check` CHECK ((`max_allowed_severity` IN ('none', 'low', 'medium', 'high', 'critical'))),
  CONSTRAINT `repository_security_policies_version_check` CHECK ((`version` >= 1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `repository_usage_counters` (
