  CONSTRAINT `saml_assertion_ids_assertion_id_check` CHECK (((CHAR_LENGTH(`assertion_id`) >= 1) AND (CHAR_LENGTH(`assertion_id`) <= 256)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `saml_request_state` (
