  PRIMARY KEY (`id`),
  KEY `ix_saml_request_state_expires_at` (`expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `scanner_db_generation` (
