  `http_status` INT NULL,
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `member_name` TEXT NULL,
  `member_type` TEXT NULL,
  `occurred_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `operation` TEXT NULL,
  `outcome` TEXT NOT NULL,
