CREATE TABLE `site_settings` (
  `brand_mark` TEXT NOT NULL DEFAULT ('NX'),
  `default_theme_id` TEXT NOT NULL DEFAULT ('notarx-dark'),
  `enabled_theme_ids` JSON NOT NULL DEFAULT (CAST('["notarx-dark","notarx-light"]' AS JSON)),
  `logo_url` TEXT NOT NULL DEFAULT (''),
  `singleton` TINYINT(1) NOT NULL DEFAULT 1,
  `site_name` TEXT NOT NULL DEFAULT ('notarx'),
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `version` BIGINT NOT NULL DEFAULT 1,
  PRIMARY KEY (`singleton`),
  CONSTRAINT `site_settings_brand_mark_check` CHECK (((CHAR_LENGTH(TRIM(`brand_mark`)) >= 1) AND (CHAR_LENGTH(TRIM(`brand_mark`)) <= 8))),
  CONSTRAINT `site_settings_default_theme_nonempty` CHECK (((CHAR_LENGTH(TRIM(`default_theme_id`)) >= 2) AND (CHAR_LENGTH(TRIM(`default_theme_id`)) <= 64))),
  CONSTRAINT `site_settings_enabled_themes_nonempty` CHECK (((JSON_LENGTH(`enabled_theme_ids`) >= 1) AND (JSON_LENGTH(`enabled_theme_ids`) <= 32))),
  CONSTRAINT `site_settings_logo_url_check` CHECK ((CHAR_LENGTH(`logo_url`) <= 262144)),
  CONSTRAINT `site_settings_singleton_check` CHECK ((`singleton` <> 0)),
  CONSTRAINT `site_settings_site_name_check` CHECK (((CHAR_LENGTH(TRIM(`site_name`)) >= 1) AND (CHAR_LENGTH(TRIM(`site_name`)) <= 80))),
  CONSTRAINT `site_settings_version_check` CHECK ((`version` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `token_signing_keys` (
  `activated_at` DATETIME(6) NULL,
  `alg` VARCHAR(255) NOT NULL,
  `created_at` DATETIME(6) NOT NULL,
  `expires_at` DATETIME(6) NULL,
  `integrity_mac` TEXT NOT NULL,
  `kid` VARCHAR(255) NOT NULL,
  `private_sealed` TEXT NOT NULL,
  `public_jwk` JSON NOT NULL,
  `published_at` DATETIME(6) NULL,
  `retired_at` DATETIME(6) NULL,
  `sealing_ref` TEXT NOT NULL DEFAULT ('local'),
  `state` TEXT NOT NULL,
  `live_token_signing_keys_one_active_idx` TINYINT(1) GENERATED ALWAYS AS (IF((`state` = 'active'), 1, NULL)) VIRTUAL NULL,
  `live_token_signing_keys_one_next_idx` TINYINT(1) GENERATED ALWAYS AS (IF((`state` = 'next'), 1, NULL)) VIRTUAL NULL,
  PRIMARY KEY (`kid`),
  UNIQUE KEY `uq_token_signing_keys_one_active_idx` (`alg`, `live_token_signing_keys_one_active_idx`),
  UNIQUE KEY `uq_token_signing_keys_one_next_idx` (`alg`, `live_token_signing_keys_one_next_idx`),
  CONSTRAINT `token_signing_keys_alg_check` CHECK ((`alg` IN ('RS256', 'ES256'))),
  CONSTRAINT `token_signing_keys_public_jwk_check` CHECK ((JSON_TYPE(`public_jwk`) = 'OBJECT')),
  CONSTRAINT `token_signing_keys_state_check` CHECK ((`state` IN ('next', 'active', 'retired')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `user_group_members` (
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `group_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `source` TEXT NOT NULL,
  `user_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  PRIMARY KEY (`group_id`, `user_id`),
  KEY `ix_user_group_members_user_id_group_id` (`user_id`, `group_id`),
  CONSTRAINT `user_group_members_source_check` CHECK ((`source` IN ('local', 'scim', 'claims')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `user_groups` (
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `display_name` TEXT NOT NULL,
  `external_id` VARCHAR(255) NOT NULL DEFAULT '',
  `global_role` TEXT NOT NULL DEFAULT ('none'),
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `provider_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  `source` TEXT NOT NULL,
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `version` BIGINT NOT NULL DEFAULT 1,
  `name_lower` VARCHAR(255) GENERATED ALWAYS AS (IF(`source` = 'local', LOWER(`display_name`), NULL)) VIRTUAL NULL,
  `live_user_groups_provider_external_id_idx` TINYINT(1) GENERATED ALWAYS AS (IF((`external_id` <> ''), 1, NULL)) VIRTUAL NULL,
  PRIMARY KEY (`id`),
  KEY `ix_user_groups_provider_id_created_at_id` (`provider_id`, `created_at`, `id`),
  KEY `ix_user_groups_provider_id_id` (`provider_id`, `id`),
  UNIQUE KEY `uq_user_groups_name_local_idx` (`name_lower`),
  UNIQUE KEY `uq_user_groups_provider_external_id_idx` (`provider_id`, `external_id`, `live_user_groups_provider_external_id_idx`),
  CONSTRAINT `user_groups_display_name_check` CHECK (((CHAR_LENGTH(TRIM(`display_name`)) >= 1) AND (CHAR_LENGTH(TRIM(`display_name`)) <= 255))),
  CONSTRAINT `user_groups_global_role_check` CHECK ((`global_role` IN ('none', 'member', 'admin'))),
  CONSTRAINT `user_groups_source_check` CHECK ((`source` IN ('local', 'scim', 'claims'))),
  CONSTRAINT `user_groups_version_check` CHECK ((`version` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `user_identities` (
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `display_name` TEXT NOT NULL DEFAULT (''),
  `email` TEXT NOT NULL DEFAULT (''),
  `email_verified` TINYINT(1) NOT NULL DEFAULT 0,
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `issuer` TEXT NOT NULL,
  `kind` TEXT NOT NULL,
  `last_login_at` DATETIME(6) NULL,
  `provider_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `scim_external_id` VARCHAR(255) NULL,
  `subject` VARCHAR(144) NULL,
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `user_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `live_user_identities_provider_scim_external_id_idx` TINYINT(1) GENERATED ALWAYS AS (IF((`scim_external_id` IS NOT NULL), 1, NULL)) VIRTUAL NULL,
  `live_user_identities_provider_subject_idx` TINYINT(1) GENERATED ALWAYS AS (IF((`subject` IS NOT NULL), 1, NULL)) VIRTUAL NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_user_identities_provider_id_user_id` (`provider_id`, `user_id`),
  KEY `ix_user_identities_provider_id_created_at_id` (`provider_id`, `created_at`, `id`),
  KEY `ix_user_identities_user_id_created_at_id` (`user_id`, `created_at`, `id`),
  UNIQUE KEY `uq_user_identities_provider_scim_external_id_idx` (`provider_id`, `scim_external_id`, `live_user_identities_provider_scim_external_id_idx`),
  UNIQUE KEY `uq_user_identities_provider_subject_idx` (`provider_id`, `subject`, `live_user_identities_provider_subject_idx`),
  CONSTRAINT `user_identities_issuer_check` CHECK ((`issuer` <> '')),
  CONSTRAINT `user_identities_key_check` CHECK (((`subject` IS NOT NULL) OR (`scim_external_id` IS NOT NULL))),
  CONSTRAINT `user_identities_kind_check` CHECK ((`kind` IN ('oidc', 'saml'))),
  CONSTRAINT `user_identities_scim_external_id_check` CHECK (((`scim_external_id` IS NULL) OR (`scim_external_id` <> ''))),
  CONSTRAINT `user_identities_subject_check` CHECK (((`subject` IS NULL) OR (`subject` <> '')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `user_sessions` (
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `expires_at` DATETIME(6) NOT NULL,
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `idp_session_id` TEXT NULL,
  `ip_address` TEXT NOT NULL DEFAULT (''),
  `kind` TEXT NOT NULL,
  `revoked_at` DATETIME(6) NULL,
  `user_agent` TEXT NOT NULL DEFAULT (''),
  `user_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_user_sessions_expires_at_id` (`expires_at`, `id`),
  KEY `ix_user_sessions_user_id` (`user_id`),
  KEY `ix_user_sessions_user_active_idx` (`user_id`, `created_at` DESC, `id`),
  CONSTRAINT `user_sessions_check` CHECK ((`expires_at` > `created_at`)),
  CONSTRAINT `user_sessions_ip_address_check` CHECK ((CHAR_LENGTH(`ip_address`) <= 64)),
  CONSTRAINT `user_sessions_kind_check` CHECK ((`kind` IN ('local_session', 'oidc', 'saml'))),
  CONSTRAINT `user_sessions_user_agent_check` CHECK ((CHAR_LENGTH(`user_agent`) <= 512))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `users` (
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `description` TEXT NOT NULL DEFAULT (''),
  `disabled_reason` TEXT NULL,
  `display_name` TEXT NOT NULL DEFAULT (''),
  `email` TEXT NOT NULL DEFAULT (''),
  `email_verified_at` DATETIME(6) NULL,
  `email_verified_by` TEXT NOT NULL DEFAULT (''),
  `email_verified_by_admin` TINYINT(1) NOT NULL DEFAULT 0,
  `failed_login_attempts` INT NOT NULL DEFAULT 0,
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `last_login_at` DATETIME(6) NULL,
  `locked_until` DATETIME(6) NULL,
  `must_change_password` TINYINT(1) NOT NULL DEFAULT 0,
  `name` VARCHAR(255) NOT NULL,
  `password_changed_at` DATETIME(6) NULL,
  `role` VARCHAR(255) NOT NULL,
  `secret_hash` TEXT NOT NULL,
  `session_version` BIGINT NOT NULL DEFAULT 1,
  `state` VARCHAR(255) NOT NULL DEFAULT 'active',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `version` BIGINT NOT NULL DEFAULT 1,
  `name_lower` VARCHAR(255) GENERATED ALWAYS AS (LOWER(`name`)) VIRTUAL NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_users_name` (`name`),
  KEY `ix_users_state_role_created_at_id` (`state`, `role`, `created_at`, `id`),
  UNIQUE KEY `uq_users_name_case_insensitive_idx` (`name_lower`),
  CONSTRAINT `users_disabled_reason_check` CHECK (((`disabled_reason` IS NULL) OR (`disabled_reason` IN ('admin', 'scim')))),
  CONSTRAINT `users_email_verified_audit_check` CHECK (((((`email_verified_by_admin` AND (`email_verified_at` IS NOT NULL)) AND (`email_verified_by` <> '')) AND (`email` <> '')) OR (((NOT `email_verified_by_admin`) AND (`email_verified_at` IS NULL)) AND (`email_verified_by` = '')))),
  CONSTRAINT `users_failed_login_attempts_check` CHECK ((`failed_login_attempts` >= 0)),
  CONSTRAINT `users_role_check` CHECK ((`role` IN ('none', 'member', 'admin'))),
  CONSTRAINT `users_session_version_check` CHECK ((`session_version` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `webhook_deliveries` (
  `attempts` INT NOT NULL DEFAULT 0,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `delivered_at` DATETIME(6) NULL,
  `event_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `event_occurred_at` DATETIME(6) NOT NULL,
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `last_error` TEXT NOT NULL DEFAULT (''),
  `last_status` INT NULL,
  `lease_expires_at` DATETIME(6) NULL,
  `lease_owner` TEXT NULL,
  `lease_token` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  `next_attempt_at` DATETIME(6) NULL,
  `state` TEXT NOT NULL DEFAULT ('pending'),
  `subscription_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `due_at` DATETIME(6) GENERATED ALWAYS AS (COALESCE(`next_attempt_at`, `lease_expires_at`)) VIRTUAL NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_webhook_deliveries_event_id_subscription_id` (`event_id`, `subscription_id`),
  KEY `ix_webhook_deliveries_created_at_desc_id_desc` (`created_at` DESC, `id` DESC),
  KEY `ix_webhook_deliveries_subscription_id_created_at_desc_id_desc` (`subscription_id`, `created_at` DESC, `id` DESC),
  KEY `ix_webhook_deliveries_actionable_idx` (`due_at`, `created_at`),
  KEY `ix_webhook_deliveries_retention_idx` (`updated_at`),
  CONSTRAINT `webhook_deliveries_attempts_check` CHECK (((`attempts` >= 0) AND (`attempts` <= 8))),
  CONSTRAINT `webhook_deliveries_check` CHECK (((`state` = 'delivering') = (((`lease_owner` IS NOT NULL) AND (`lease_token` IS NOT NULL)) AND (`lease_expires_at` IS NOT NULL)))),
  CONSTRAINT `webhook_deliveries_check1` CHECK (((`state` = 'succeeded') = (`delivered_at` IS NOT NULL))),
  CONSTRAINT `webhook_deliveries_check2` CHECK (((`state` IN ('pending', 'retrying')) = (`next_attempt_at` IS NOT NULL))),
  CONSTRAINT `webhook_deliveries_last_error_check` CHECK ((CHAR_LENGTH(`last_error`) <= 1024)),
  CONSTRAINT `webhook_deliveries_last_status_check` CHECK (((`last_status` IS NULL) OR ((`last_status` >= 100) AND (`last_status` <= 599)))),
  CONSTRAINT `webhook_deliveries_state_check` CHECK ((`state` IN ('pending', 'delivering', 'retrying', 'succeeded', 'dead')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `webhook_subscriptions` (
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `enabled` TINYINT(1) NOT NULL DEFAULT 1,
  `endpoint_url` TEXT NOT NULL,
  `event_types` JSON NOT NULL,
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `secret_ciphertext` TEXT NOT NULL,
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `version` BIGINT NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_webhook_subscriptions_name` (`name`),
  CONSTRAINT `webhook_subscriptions_endpoint_url_check` CHECK (((CHAR_LENGTH(`endpoint_url`) >= 1) AND (CHAR_LENGTH(`endpoint_url`) <= 2048))),
  CONSTRAINT `webhook_subscriptions_event_types_check` CHECK ((((JSON_TYPE(`event_types`) = 'ARRAY') AND (JSON_LENGTH(`event_types`) > 0)) AND JSON_CONTAINS(CAST('["artifact.published", "artifact.scan.completed", "artifact.quarantined", "artifact.released", "artifact.promoted", "promotion.pending_approval", "promotion.approved", "promotion.rejected", "promotion.failed", "replication.completed", "replication.failed", "repository.visibility_changed"]' AS JSON), `event_types`))),
  CONSTRAINT `webhook_subscriptions_name_check` CHECK (((CHAR_LENGTH(`name`) >= 1) AND (CHAR_LENGTH(`name`) <= 128))),
  CONSTRAINT `webhook_subscriptions_secret_ciphertext_check` CHECK ((`secret_ciphertext` <> '')),
  CONSTRAINT `webhook_subscriptions_version_check` CHECK ((`version` >= 1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `workload_issuers` (
  `allow_private_network` TINYINT(1) NOT NULL DEFAULT 0,
  `allowed_algs` JSON NOT NULL DEFAULT (CAST('["RS256","ES256","EdDSA"]' AS JSON)),
  `audiences` JSON NOT NULL,
  `ca_bundle_pem` TEXT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `issuer` VARCHAR(512) NOT NULL,
  `jwks_mode` TEXT NOT NULL,
  `jwks_uri` TEXT NULL,
  `kind` TEXT NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `state` TEXT NOT NULL DEFAULT ('active'),
  `static_jwks` JSON NULL,
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `version` BIGINT NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_workload_issuers_issuer` (`issuer`),
  UNIQUE KEY `uq_workload_issuers_name` (`name`),
  CONSTRAINT `workload_issuers_allowed_algs_check` CHECK (((JSON_LENGTH(`allowed_algs`) > 0) AND JSON_CONTAINS(JSON_ARRAY('RS256', 'ES256', 'EdDSA'), `allowed_algs`))),
  CONSTRAINT `workload_issuers_audiences_check` CHECK ((JSON_LENGTH(`audiences`) > 0)),
  CONSTRAINT `workload_issuers_jwks_mode_check` CHECK ((`jwks_mode` IN ('discovery', 'static'))),
  CONSTRAINT `workload_issuers_kind_check` CHECK ((`kind` IN ('github_actions', 'gitlab_ci', 'kubernetes', 'generic'))),
  CONSTRAINT `workload_issuers_state_check` CHECK ((`state` IN ('active', 'disabled'))),
  CONSTRAINT `workload_issuers_static_jwks_check` CHECK (((`jwks_mode` <> 'static') OR (`static_jwks` IS NOT NULL)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `workload_jti_seen` (
  `expires_at` DATETIME(6) NOT NULL,
  `issuer_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `jti_hash` VARBINARY(64) NOT NULL,
  PRIMARY KEY (`issuer_id`, `jti_hash`),
  KEY `ix_workload_jti_seen_expires_at` (`expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE `workload_trust_policies` (
  `conditions` JSON NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `expires_at` DATETIME(6) NULL,
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `issuer_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `max_token_ttl_seconds` INT NOT NULL DEFAULT 900,
  `name` VARCHAR(255) NOT NULL,
  `service_account_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `single_use` TINYINT(1) NOT NULL DEFAULT 0,
  `state` VARCHAR(255) NOT NULL DEFAULT 'active',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `version` BIGINT NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_workload_trust_policies_name` (`name`),
  KEY `ix_workload_trust_policies_issuer_id_state` (`issuer_id`, `state`),
  KEY `ix_workload_trust_policies_service_account_id` (`service_account_id`),
  CONSTRAINT `workload_trust_policies_conditions_check` CHECK ((JSON_TYPE(`conditions`) = 'ARRAY')),
  CONSTRAINT `workload_trust_policies_state_check` CHECK ((`state` IN ('active', 'disabled'))),
  CONSTRAINT `workload_trust_policies_ttl_check` CHECK ((`max_token_ttl_seconds` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

